// launch-factory: 뉴스레터 구독 명단 조립. 순서: 요청 제한(DB) → 멱등 키 → 입력 검사 → Turnstile → 저장 → 확인 메일(이중 동의).
// 구독은 확인 링크를 눌러야 완료되고, 그때 구독 완료 안내(전송자·동의한 날·결과 — 정보통신망법 제50조제7항)가 한 통 간다. 수신거부는 로그인 없이 링크 하나(만료 없음).
// 이 항목은 명단만 관리한다 — 보내기(캠페인)는 하지 않는다. 보낼 때는 service.listSubscribed 로 구독자와 그의 서명 수신거부 링크를 읽어 간다.
// 확인하지 않은 신청 14일·수신거부 기록 1년이 지나면 Cron(/api/cron/newsletter)이 지운다.
import { hitRateLimit } from "@launch-factory/db"
import { createNewsletterService, type NewsletterService } from "@launch-factory/newsletter"
import { createRateLimiter, ipAddressFromEnv, warnNoIpOnce } from "@launch-factory/security/rate-limit"
import { createTurnstile } from "@launch-factory/security/turnstile"
import { appUrl, PRODUCT_NAME } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { env, required } from "@/lib/launch/env"
import { linkSecret } from "@/lib/launch/link-secret"
import { mailer } from "@/lib/launch/mailer"

let cached: Promise<NewsletterService> | undefined

export function newsletter(): Promise<NewsletterService> {
  return (cached ??= build())
}

async function build(): Promise<NewsletterService> {
  const db = await database()
  const live = env().LF_MODE === "live"
  return createNewsletterService({
    db,
    mailer: mailer(),
    // 믿을 IP 머리는 환경이 정한다(대장 D205). 문의·인증 항목과 같은 함수라 같은 사람을 같은 IP 로 센다
    limiter: createRateLimiter({ store: { hit: (key, windowMs, now) => hitRateLimit(db, key, windowMs, now) }, ipAddress: ipAddressFromEnv(process.env), onNoIp: warnNoIpOnce() }),
    turnstile: createTurnstile(live ? { mode: "live", secretKey: required("TURNSTILE_SECRET_KEY") } : { mode: "mock" }),
    secret: linkSecret(),
    baseUrl: appUrl(),
    productName: PRODUCT_NAME,
  })
}

// launch-factory: 관리 화면 구획 — 뉴스레터 구독 명단(계획 3d). 관리자만 들어온다(이 부품에는 소유자 이메일이 없다).
// 구획은 선언이다 — 접근 벽·확인 입력 벽·기록·연락처 가리기는 콘솔(@launch-factory/admin-console)이 한다. 등록은 lib/launch/admin-console.ts 의 ADMIN_SECTIONS 한 줄.
// 보여 주는 것: 표(이메일은 가려서, 상태·출처·동의한 날) → 기록(동의 증빙: 동의 문구 판·동의/확인/철회 시각·보유 기한). 서명 링크·토큰은 어느 쪽에도 싣지 않는다(수신거부 링크는 구독자 본인의 열쇠다).
// 행동은 하나: 수신거부 대행(mark-unsubscribed, 위험 — 구독자가 되돌리려면 새로 신청해 새 확인을 거쳐야 한다). 구독자가 요청한 철회를 대신 처리할 뿐이고(정보통신망법 제50조⑥ — 철회는 지체 없이),
// 구독을 만들거나 확인해 주는 길은 만들지 않는다 — 동의는 구독자 본인의 것이다. 상태 이름은 명단의 이름 그대로다(pending · subscribed · unsubscribed).
import { defineSection, refuse } from "@launch-factory/admin-console"
import type { SubscriberAdminView } from "@launch-factory/newsletter"
import { newsletter } from "@/lib/launch/newsletter"

const STATUSES = ["pending", "subscribed", "unsubscribed"] as const
type Status = (typeof STATUSES)[number]

const isStatus = (v: string | undefined): v is Status => STATUSES.includes(v as Status)
const day = (d: Date | null): string | null => (d ? d.toISOString().slice(0, 10) : null)
const stamp = (d: Date | null, none = "—"): string => (d ? `${d.toISOString().slice(0, 16).replace("T", " ")} UTC` : none)

export default defineSection({
  id: "newsletter",
  part: "newsletter",
  label: "Newsletter",
  audience: "admin",
  statuses: STATUSES,
  serverSearch: true, // 서버 검색: 이메일 부분 일치(listSubscribersForAdmin)
  columns: [
    { id: "email", label: "Email", kind: "contact", primary: true },
    { id: "status", label: "Status", kind: "status", filter: true },
    { id: "source", label: "Form", kind: "text", secondary: true },
    { id: "consentAt", label: "Consented", kind: "date", secondary: true },
  ],
  list: async (_actor, { search, status, limit, offset }) => {
    const page = await (await newsletter()).listForAdmin({ ...(isStatus(status) ? { status } : {}), ...(search ? { search } : {}), limit, offset })
    return { items: page.items, total: page.total }
  },
  key: (row: SubscriberAdminView) => row.id,
  cells: (row) => ({ email: row.email, status: row.status, source: row.source, consentAt: day(row.consentAt) }),
  load: async (_actor, id) => (await (await newsletter()).getForAdmin(id)) ?? null,
  view: (rec) => ({
    // 제목은 주소·화면 머리에 그대로 나가므로 이메일 대신 기록 번호 앞자리를 쓴다
    title: `Subscriber ${rec.id.slice(0, 8)}`,
    summary: [
      { label: "Email", value: rec.email },
      { label: "Status", value: rec.status, kind: "status" },
      { label: "Language", value: rec.locale },
      { label: "Form", value: rec.source },
      { label: "Consent version", value: rec.consentVersion },
      { label: "Consent given", value: stamp(rec.consentAt) },
      { label: "Confirmation mail sent", value: stamp(rec.confirmSentAt) },
      { label: "Confirmed", value: stamp(rec.confirmedAt, "Not confirmed") },
      { label: "Unsubscribed", value: stamp(rec.unsubscribedAt) },
      { label: "Record kept until", value: stamp(rec.expiresAt, "While subscribed") },
    ],
  }),
  actions: {
    "mark-unsubscribed": {
      label: "Unsubscribe",
      danger: true,
      when: (rec) => rec.status !== "unsubscribed",
      run: async (_actor, rec) => {
        const done = await (await newsletter()).withdraw(rec.id)
        if (!done.ok) return refuse("not_found")
        return { message: "Unsubscribed. The consent record is kept until its retention date." }
      },
    },
  },
})

// launch-factory: 뉴스레터 구독 신청 경로(POST, FormData 또는 JSON). 429 + Retry-After · 봇 400 · 칸 오류 400 · 확인 불가 503 · 처리 중 409.
// 폼 칸: email · consent("yes" — 체크박스, 미리 체크하지 않는다) · source(선택, 폼 이름표). 숨은 입력 둘을 더한다: Turnstile 토큰 `cf-turnstile-response`, 폼을 열 때 만든 `idempotencyKey`.
import { createNewsletterHandlers } from "@launch-factory/newsletter"
import { newsletter } from "@/lib/launch/newsletter"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function POST(request: Request) {
  return createNewsletterHandlers(await newsletter()).subscribe(request)
}

// launch-factory: 구독 확인 링크(메일의 「구독 확인」 단추). 주소의 `?t=` 는 서명 토큰(7일)이다.
//   GET  — 열면 구독이 확정되고 /email?list=newsletter&r=confirmed|invalid|withdrawn 으로 303. 두 번 열어도 안전하다.
//   POST — 같은 처리를 JSON 으로. 메일 보안 프로그램이 링크를 미리 여는 환경이면 /email 쪽이 단추를 보이고 이 경로로 POST 해 확정한다.
import { createNewsletterHandlers } from "@launch-factory/newsletter"
import { newsletter } from "@/lib/launch/newsletter"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  return createNewsletterHandlers(await newsletter()).confirm(request)
}

export async function POST(request: Request) {
  return createNewsletterHandlers(await newsletter()).confirm(request)
}

// launch-factory: 뉴스레터 수신거부(정보통신망법 시행령 별표 6 — 로그인 없이, 연락처 외 정보를 요구하지 않고, 링크 하나로). 주소의 `?t=` 는 서명 토큰이고 만료가 없다.
//   GET  — 본문 링크를 열면 그 자리에서 철회하고 /email?list=newsletter&r=unsubscribed 로 303. 두 번 열어도(미리 열기 포함) 같은 결과다.
//   POST — Gmail·Yahoo 의 「한 번에 수신거부」(RFC 8058, List-Unsubscribe-Post: List-Unsubscribe=One-Click). 쿠키·로그인 없이 같은 처리, 200/400 JSON.
// 이 주소가 보내는 메일마다 단 수신거부 링크이자 List-Unsubscribe 헤더의 주소다(service.listSubscribed 의 unsubscribeUrl).
import { createNewsletterHandlers } from "@launch-factory/newsletter"
import { newsletter } from "@/lib/launch/newsletter"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  return createNewsletterHandlers(await newsletter()).unsubscribe(request)
}

export async function POST(request: Request) {
  return createNewsletterHandlers(await newsletter()).unsubscribe(request)
}

// launch-factory: 뉴스레터 파기 Cron(하루 한 번 권장). 확인하지 않은 신청(14일)과 수신거부 기록(1년)을 지운다. 구독 중인 사람은 지우지 않는다.
// vercel.json 에 `{ "crons": [{ "path": "/api/cron/newsletter", "schedule": "30 4 * * *" }] }` 를 더한다. CRON_SECRET 이 없으면 401 이다.
import { cronAuthorized, unauthorized } from "@/lib/launch/cron"
import { newsletter } from "@/lib/launch/newsletter"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  if (!cronAuthorized(request)) return unauthorized()
  return Response.json({ purged: await (await newsletter()).purgeExpired() })
}

// launch-factory: DB 연결. mock 은 메모리 PGlite(키 없이 켜진다), live 는 DATABASE_URL(Supabase 풀러 6543 — prepared statement 끔은 패키지가 한다).
// mock 의 마이그레이션은 이 앱에 설치된 db/migrations 를 쓴다(번들 안에서는 패키지 폴더를 찾을 수 없다).
import { join } from "node:path"
import { db, type Database } from "@launch-factory/db"
import { env, required } from "@/lib/launch/env"

let cached: Promise<Database> | undefined

/**
 * mock 의 메모리 DB 는 프로세스 하나에 하나다. 서버 번들은 쪽·서버 액션·경로 처리기(app/api)로 갈라져 같은 모듈이 번들마다 따로 불리므로(Next/Turbopack),
 * 모듈 변수에만 두면 번들 수만큼 DB 가 생겨 경로 처리기(웹훅·크론·/api/auth)와 쪽이 서로 다른 데이터를 보았다(관리 화면 시험 실측: 경로로 만든 세션이 쪽에서 안 보였다).
 * 그래서 globalThis 에 둔다. live 는 연결 문자열이 같은 DB 를 가리키므로 모듈 변수로 충분하다.
 */
const mockStore = globalThis as { __lfMockDb?: Promise<Database> }

export function database(): Promise<Database> {
  if (env().LF_MODE === "mock") return (mockStore.__lfMockDb ??= db.local({ migrationsFolder: join(process.cwd(), "db", "migrations") }))
  return (cached ??= Promise.resolve(db(required("DATABASE_URL"))))
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}

// launch-factory: 제품마다 고치는 값. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
import type { Locale } from "@launch-factory/email"
import { env, required } from "@/lib/launch/env"

export const PRODUCT_NAME = "My Product"
/** 사용자 칸(user.locale)이 비었을 때 메일·오류 문구의 언어 */
export const DEFAULT_LOCALE: Locale = "en"
/** 가입 때 동의 기록에 남길 약관·개인정보 처리방침의 판. 문서를 고치면 올린다 */
export const CONSENT_VERSIONS = { terms: "2026-09-30", privacy: "2026-09-30" }
/** 결제 메일이 가리키는 화면 경로 */
export const ROUTES = { billing: "/account/billing", acceptPriceChange: "/account/billing/price-change", decline: "/account/billing/cancel", security: "/forgot-password", contact: "/contact" }

/** 앱 주소. mock 에서는 로컬 주소로 켜지고, live 에서는 NEXT_PUBLIC_APP_URL 이 필수다 */
export function appUrl(): string {
  // 빈 문자열은 없는 것으로 본다 — shadcn CLI 가 envVars 이름을 `NAME=`(빈 값)으로 .env.local 에 적는다
  return process.env.NEXT_PUBLIC_APP_URL || (env().LF_MODE === "mock" ? "http://localhost:3000" : required("NEXT_PUBLIC_APP_URL"))
}

// launch-factory: Cron 경로 인증. Vercel Cron 은 CRON_SECRET 이 있으면 `Authorization: Bearer <값>` 을 붙여 부른다
// (https://vercel.com/docs/cron-jobs/manage-cron-jobs#securing-cron-jobs). 값이 없거나 다르면 거절한다 — 비밀이 없으면 열어 두지 않는다.
import { timingSafeEqual } from "node:crypto"

export function cronAuthorized(request: Request): boolean {
  const secret = process.env.CRON_SECRET
  if (!secret) return false
  const given = request.headers.get("authorization") ?? ""
  const want = `Bearer ${secret}`
  return given.length === want.length && timingSafeEqual(Buffer.from(given), Buffer.from(want))
}

export const unauthorized = () => Response.json({ error: "unauthorized" }, { status: 401 })

// launch-factory: 로그인 없이 누르는 메일 링크(수신거부 · 계속 받기 · 가입 안 했어요)의 서명 비밀.
// 앱 비밀(BETTER_AUTH_SECRET)에서 용도를 섞어 파생한 값이라 세션 서명과 섞이지 않는다(HMAC 입력이 다르다). 새 환경 변수를 만들지 않는다.
// live 는 BETTER_AUTH_SECRET(32자 이상)이 필수다. mock 에서 없으면 프로세스마다 새로 만든다 — 재시작하면 그 전에 만든 링크는 열리지 않는다(개발 중에만 그렇다).
import { createHmac, randomBytes } from "node:crypto"
import { env, required } from "@/lib/launch/env"

let mockBase: string | undefined

export function linkSecret(): string {
  const e = env()
  const base = e.LF_MODE === "live" ? required("BETTER_AUTH_SECRET") : (e.BETTER_AUTH_SECRET ?? (mockBase ??= randomBytes(32).toString("hex")))
  return createHmac("sha256", base).update("lf-mail-links-v1").digest("hex")
}

// launch-factory: 마이그레이션 적용. 사용법: DATABASE_URL=<직접 연결(5432)> node db/migrate.mjs
// 이 폴더의 migrations/ 를 순서대로 적용한다. 이미 적용한 파일은 건너뛴다(drizzle 기록 표).
import { fileURLToPath } from "node:url"
import postgres from "postgres"
import { drizzle } from "drizzle-orm/postgres-js"
import { migrate } from "drizzle-orm/postgres-js/migrator"

const url = process.env.DATABASE_URL
if (!url) {
  console.error("DATABASE_URL is not set")
  process.exit(1)
}
if (new URL(url).port === "6543") {
  console.error("Use the direct connection (port 5432) for migrations, not the transaction pooler (6543).")
  process.exit(1)
}

const client = postgres(url, { max: 1 })
try {
  await migrate(drizzle(client), { migrationsFolder: fileURLToPath(new URL("./migrations", import.meta.url)) })
  console.log("migrations applied")
} finally {
  await client.end()
}

// 뉴스레터 구독 명단(Task 4, plan-3c). 로그인 없는 방문자의 이메일 구독이라 user 표와 이어지지 않는다.
// - 이중 동의: 신청하면 status=pending(확인 메일 발송) → 확인 링크를 누르면 subscribed. 동의는 신청한 순간의 것이라 consent_at 은 신청 시각이다.
//   consent_version 은 그때 화면에 있던 동의 문구의 판이다(정보통신망법 제50조① — 명시적 사전 동의의 증빙).
// - 수신거부: status=unsubscribed + unsubscribed_at. 동의·확인 증빙은 지우지 않고(분쟁 대비) expires_at 에 보유 기간을 둔다.
// - expires_at: pending(확인 안 한 신청)과 unsubscribed 에만 있고, 지나면 purgeExpiredSubscribers 가 지운다(개인정보 보호법 제21조①).
//   subscribed 는 null — 구독 중인 사람은 지우지 않는다.
// 저장하지 않는 것: IP·브라우저 정보·토큰(링크의 서명 토큰은 비밀값에서 매번 만든다). 시각은 앱이 넣는다(Task 4 D26 규칙).
import { sql } from "drizzle-orm"
import { check, index, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core"

const tz = { withTimezone: true } as const

export const NEWSLETTER_STATUSES = ["pending", "subscribed", "unsubscribed"] as const
export type NewsletterStatus = (typeof NEWSLETTER_STATUSES)[number]

export const newsletterSubscribers = pgTable(
  "newsletter_subscribers",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** 소문자로 맞춘 주소. 같은 사람이 두 번 들어오지 못하게 unique */
    email: text("email").notNull().unique(),
    status: text("status").$type<NewsletterStatus>().notNull(),
    locale: text("locale").notNull(),
    /** 어느 폼에서 왔는지(블록 id 등, 개인정보 아님) */
    source: text("source").notNull(),
    consentVersion: text("consent_version").notNull(),
    consentAt: timestamp("consent_at", tz).notNull(),
    confirmSentAt: timestamp("confirm_sent_at", tz),
    confirmedAt: timestamp("confirmed_at", tz),
    unsubscribedAt: timestamp("unsubscribed_at", tz),
    createdAt: timestamp("created_at", tz).notNull(),
    expiresAt: timestamp("expires_at", tz),
  },
  (t) => [
    index("newsletter_subscribers_status_id_idx").on(t.status, t.id),
    index("newsletter_subscribers_expires_at_idx").on(t.expiresAt),
    check("newsletter_subscribers_status_check", sql`${t.status} in ('pending', 'subscribed', 'unsubscribed')`),
  ],
).enableRLS() // 공개 표는 RLS 를 명시로 켠다(정책은 만들지 않는다 — 0010_explicit_rls)

-- 접속기록 위·변조 방지(「개인정보의 안전성 확보조치 기준」 제8조제3항). access_logs는 추가 전용이다.
--   UPDATE·TRUNCATE: 항상 거부
--   DELETE: 접속일시가 1년(제8조제1항 최소 보관 기간)을 넘은 행만 허용 — 파기 작업이 2년 설정이면 그보다 늦게 지운다
-- 트리거는 역할과 상관없이 걸린다(표 소유자가 트리거를 끄는 것까지는 막지 못한다 — 해시 사슬은 다음 단계, docs/qa/task-3-report.md).
